/**
 * Web derivative renditions generated by the media-index pipeline
 * (`generate-derivatives`). They live under a `thumbnails/` directory of the
 * media file node and are named by their size class (target box from
 * `modules/archive/config/sizes.yaml`): images/video as `<width>x<height>.<ext>`,
 * audio as `<bitrate>-<sampleRate>.<ext>`.
 *
 * These names couple the UI to sizes.yaml — changing a size there means updating
 * these constants and re-running `regenerate --force --prune`.
 *
 * Images are AVIF, video is AV1 in MP4, audio is AAC in MP4.
 *
 * Audio carries *both*: the `.m4a` it plays, and a rendered waveform at the same image
 * sizes a photo has (EMS's `audio.waveform`). That is why nothing here special-cases it —
 * a waveform is a picture, and the tile, the srcset and the cover card all just work.
 *
 * Video carries both too, and additionally has *two* mp4s that are not a ladder:
 * `1920x1080.mp4` is what the lightbox plays, `480x480.mp4` is the silent 20-second clip
 * a grid tile hover-plays. Nothing in either name says which is which beyond its box —
 * that is the convention throughout, and `PREVIEW_NAME` is where it is written down.
 */

import { fileUrl } from './file-url.ts';

export type MediaKind = 'photo' | 'video' | 'audio';

/**
 * The picture as a viewer sees it — rotation and pixel aspect already applied — which is
 * what `displayDims` in `./justified-layout.ts` computes from a file node's stored raster.
 */
type PictureDims = { width: number; height: number };

/**
 * Every `contain` box of the still-image ladder in sizes.yaml, smallest first. The 320
 * `cover` thumbnail is not one: it is cropped to an exact square and always made.
 */
const CONTAIN_BOXES = [512, 800, 1600, 2560];

/**
 * Which of `CONTAIN_BOXES` a picture of `dims` actually has.
 *
 * `contain` never upscales, so the first box the picture fits inside stores it at its own
 * size, and `generate-derivatives` does not make the boxes above it: they would hold the
 * very same pixels under a bigger name. Every box the picture overflows is kept, plus that
 * first fitting one — so a 600x400 photo has the 512 and the 800, nothing above. Unknown
 * dimensions (a file without stored `width`/`height`) means every box — generation makes
 * the full set for such a file, for the same reason.
 *
 * A consumer that uses a subset of the ladder (video posters stop at 1600, the lightbox
 * ladder starts at 800) intersects with this rather than applying the rule to its subset:
 * the rule is about which box first fits, and that is a property of the whole ladder.
 *
 * Mirrors `redundantSizes` in modules/archive/bin/generate-derivatives; the two must change
 * together.
 */
export function availableBoxes(dims?: PictureDims): number[] {
  if (!dims || !(dims.width > 0) || !(dims.height > 0)) return [...CONTAIN_BOXES];
  const kept: number[] = [];
  for (const box of CONTAIN_BOXES) {
    kept.push(box);
    if (box >= dims.width && box >= dims.height) break;
  }
  return kept;
}

/**
 * How wide a `contain` rendition of `dims` comes out of a square `box`: scaled down to fit
 * when it overflows, its own width when it does not. What a `w` descriptor should say.
 */
function renderedWidth(box: number, dims: PictureDims): number {
  const scale = Math.min(1, box / dims.width, box / dims.height);
  return Math.round(dims.width * scale);
}

/** The largest box a picture of `dims` has, capped at `max`. */
const largestBox = (max: number, dims?: PictureDims): number => availableBoxes(dims).filter((box) => box <= max).at(-1) ?? max;

/**
 * Square thumbnail (image `thumb`, 320x320 cover), for what crops to a square anyway:
 * the 48px map marker and the album cover card.
 * The media grid uses `GRID_NAME`.
 */
export const THUMB_NAME = '320x320.avif';

/** Justified-grid tile / video poster (image `grid`, 512x512 contain). */
export const GRID_NAME = '512x512.avif';

/**
 * What a tile falls back to when the `grid` rendition is missing — one the backfill has
 * not reached.
 *
 * Deliberately the next *contain* size and never the 320 `cover` thumbnail: the square
 * crop has already thrown away the sides of the picture, and dropping it into a
 * non-square slot crops it a second time, so a whole album would read as squares in a
 * justified grid. Six times the bytes for the tiles that need it is the better trade.
 */
export const GRID_FALLBACK_NAME = '800x800.avif';

/** The box `GRID_FALLBACK_NAME` is, for `gridFallbackUrl` to check a small picture has it. */
const GRID_FALLBACK_BOX = 800;

/**
 * The aspect a `contain` waveform is drawn at — a banner, since a waveform is a picture of
 * a timeline. Keep in step with `WAVEFORM_STYLE` in modules/archive/lib/media/image-ladder.ts.
 *
 * Unlike a photo's, this aspect is known before the image loads: the picture is synthesised
 * rather than captured, so every audio tile is this shape. The grid uses it as the
 * pre-measure aspect, which is what stops audio tiles laying out at the photo default and
 * then jumping once the waveform decodes.
 */
export const WAVEFORM_ASPECT = 3;

/**
 * Contain boxes the grid can draw a tile from, smallest first. `grid` is the intended
 * one; the two above it are there so a 2x display at a tall row height still gets
 * enough pixels rather than upscaling a 512.
 */
const GRID_BOXES = [512, 800, 1600];

/**
 * The photo sizes the browser chooses between, smallest first. Widths are the
 * target box; `imageSrcSet` turns them into `w` descriptors, clamped to the
 * picture's own width when that is known, since a `contain` rendition is never
 * wider than its box and never wider than its source either.
 */
const IMAGE_LADDER: { name: string; width: number }[] = [
  { name: '800x800.avif', width: 800 },
  { name: '1600x1600.avif', width: 1600 },
  { name: '2560x2560.avif', width: 2560 },
];

/** Lightbox/playback rendition per media kind — the `src` fallback for the ladder. */
export const DISPLAY_DERIVATIVE: Record<MediaKind, string> = {
  photo: '1600x1600.avif',
  video: '1920x1080.mp4',
  audio: '128k-44100.m4a',
};

/**
 * Codecs of the video rendition, for a `<source type>`. Being explicit lets a
 * browser that cannot decode AV1 skip the source and show the poster instead of
 * a black frame.
 *
 * av01.0.08M.08 is Main profile, level 4.0, 8-bit — what SVT-AV1/NVENC emit at
 * 1080p; mp4a.40.2 is AAC-LC.
 */
export const VIDEO_SOURCE_TYPE = 'video/mp4; codecs="av01.0.08M.08,mp4a.40.2"';

/**
 * Hover-play clip for a grid tile (video `preview`: 480x480 contain, silent, 20 seconds
 * from 00:00:01).
 *
 * It starts where the `grid` poster was taken, so swapping the still for the clip shows
 * the same frame twice rather than a jump cut. It carries no audio track — a grid preview
 * always plays muted, so the bytes would never be heard.
 *
 * Unlike `DISPLAY_DERIVATIVE`, a tile sets this as a bare `src` rather than a `<source
 * type>`: a browser that cannot decode AV1 must *fail* here, so the tile hears the error,
 * remembers there is no usable preview and leaves the still in place. A typed `<source>`
 * would be skipped silently and leave a transparent video mounted over the picture.
 */
export const PREVIEW_NAME = '480x480.mp4';

/**
 * The box a video's poster frame is cut at, before `posterUrl` steps down for a smaller video: a
 * `contain` box rather than `THUMB_NAME`, because the square 320 is a centre crop, and a cropped
 * poster behind a `contain`-fitted video is the wrong picture in the wrong shape.
 */
const POSTER_BOX = 1600;

/** The box `DISPLAY_DERIVATIVE.photo` is, for `displayUrl` to step down from likewise. */
const DISPLAY_BOX = 1600;

/**
 * Grid thumbnail URL. Falls back to the original when the `thumbnails/` dir is
 * absent (file not yet indexed / migrated).
 *
 * Audio has this rendition too: the waveform is drawn square for a `cover` target
 * rather than centre-cropping a banner, so the square consumers get a whole picture.
 */
export function thumbnailUrl(path: string, hasThumbnails: boolean): string {
  return hasThumbnails ? `${fileUrl(path)}/thumbnails/${THUMB_NAME}` : fileUrl(path);
}

/**
 * Justified-grid tile URL. Falls back to the original when the `thumbnails/` dir is
 * absent.
 *
 * A `thumbnails/` dir can lack the 512x512, so this URL can still 404 — the tile handles
 * that by falling back to `thumbnailUrl`, which is why the grid does not have to wait for
 * a backfill.
 */
export function gridUrl(path: string, hasThumbnails: boolean): string {
  return hasThumbnails ? `${fileUrl(path)}/thumbnails/${GRID_NAME}` : fileUrl(path);
}

/**
 * Aspect-preserving stand-in for `gridUrl` when that rendition is absent.
 *
 * With `dims`, the original instead when the picture is too small for the 800 box to have
 * been generated — the tile's next step is the original anyway, so this only saves a 404.
 */
export function gridFallbackUrl(path: string, hasThumbnails: boolean, dims?: PictureDims): string {
  if (!hasThumbnails) return fileUrl(path);
  return availableBoxes(dims).includes(GRID_FALLBACK_BOX) ? `${fileUrl(path)}/thumbnails/${GRID_FALLBACK_NAME}` : fileUrl(path);
}

/**
 * `srcset` for a grid tile.
 *
 * The aspect ratio is known here, so the `w` descriptors are the rendition's *actual*
 * width rather than its bounding box: a `contain` box B renders a portrait at `B * aspect`
 * wide. Over-promising the width makes the browser pick a size smaller than it needs on
 * portraits.
 *
 * With `dims` the ladder is cut down to the sizes the picture has (`availableBoxes`) and the
 * top one is described at the picture's own width: a 600x400 photo has only the 512 and the
 * 800, and the 800 holds 600 pixels, not 800. Over-promising *that* way makes the browser
 * pick a size that gives it fewer real pixels than it asked for. Without `dims` the aspect
 * alone still gives the right answer for anything larger than the ladder.
 *
 * Empty string when there is nothing to offer — callers must then omit the attribute
 * entirely, since an empty `srcset` makes some browsers ignore `src` as well.
 */
export function gridSrcSet(
  path: string,
  hasThumbnails: boolean,
  aspect: number,
  dims?: PictureDims,
): string {
  if (!hasThumbnails || !Number.isFinite(aspect) || aspect <= 0) {
    return '';
  }

  const seen = new Set<number>();
  const entries: string[] = [];

  const available = availableBoxes(dims);
  for (const box of GRID_BOXES) {
    if (!available.includes(box)) continue;
    const rendered = dims ? renderedWidth(box, dims) : Math.round(box * Math.min(1, aspect));
    if (seen.has(rendered)) continue;
    seen.add(rendered);
    entries.push(`${fileUrl(path)}/thumbnails/${box}x${box}.avif ${rendered}w`);
  }

  return entries.join(', ');
}

/**
 * Poster frame for a `<video>`, or '' when there is no rendition to point at (the caller
 * must then omit the attribute — a `poster=""` paints a broken-image icon over the video).
 *
 * With `dims`, the largest poster the video actually has: a 640x480 clip fits the 800 box,
 * so `generate-derivatives` never made its 1600.
 */
export function posterUrl(path: string, type: MediaKind, hasThumbnails: boolean, dims?: PictureDims): string {
  if (!hasThumbnails || type !== 'video') return '';
  const box = largestBox(POSTER_BOX, dims);
  return `${fileUrl(path)}/thumbnails/${box}x${box}.avif`;
}

/**
 * Hover-play clip URL, or '' when there is none to ask for.
 *
 * Never falls back to the 1080p rendition. That is the whole reason this one exists: a
 * grid asks for the clip as the pointer crosses a row, and on a phone as you scroll, so
 * megabytes of full-HD for a 200px slot is exactly what must not happen. A video without
 * a preview simply stays a still.
 *
 * `hasThumbnails` only promises the directory exists, so during a backfill this URL can
 * still 404 — the tile treats that as "no preview" and does not ask again.
 */
export function previewUrl(path: string, type: MediaKind, hasThumbnails: boolean): string {
  return hasThumbnails && type === 'video' ? `${fileUrl(path)}/thumbnails/${PREVIEW_NAME}` : '';
}

/**
 * Full/display URL. Falls back to the original when no `thumbnails/` dir.
 *
 * With `dims`, a photo gets the largest size it actually has rather than the fixed 1600:
 * a 1200x800 photo fits the 1600 box, so its ladder stops there and nothing above it was
 * made — and a 600x400 one stops at the 800.
 */
export function displayUrl(path: string, type: MediaKind, hasThumbnails: boolean, dims?: PictureDims): string {
  if (!hasThumbnails) return fileUrl(path);
  if (type !== 'photo') return `${fileUrl(path)}/thumbnails/${DISPLAY_DERIVATIVE[type]}`;
  const box = largestBox(DISPLAY_BOX, dims);
  return `${fileUrl(path)}/thumbnails/${box}x${box}.avif`;
}

/**
 * `srcset` for a photo, so the browser fetches the size its viewport and pixel
 * density actually need rather than one fixed size.
 *
 * With `dims`, only the sizes the photo has, and the top one described at the photo's own
 * width — see `gridSrcSet` for why a box-sized descriptor on a small source is a lie the
 * browser acts on. Without `dims`, the box widths: right for any photo larger than 2560
 * and the best available guess for the rest.
 *
 * Empty string for anything without derivatives or that is not a photo — callers
 * must omit the attribute entirely in that case, since an empty `srcset` makes
 * some browsers ignore `src` as well.
 */
export function imageSrcSet(path: string, type: MediaKind, hasThumbnails: boolean, dims?: PictureDims): string {
  if (!hasThumbnails || type !== 'photo') {
    return '';
  }

  const available = availableBoxes(dims);
  const seen = new Set<number>();
  const entries: string[] = [];

  for (const { name, width } of IMAGE_LADDER) {
    if (!available.includes(width)) continue;
    const rendered = dims ? renderedWidth(width, dims) : width;
    if (seen.has(rendered)) continue;
    seen.add(rendered);
    entries.push(`${fileUrl(path)}/thumbnails/${name} ${rendered}w`);
  }

  return entries.join(', ');
}
